lessons.solution_code:
def ensure_non_negative(fn):
    def wrapper(x, *args, **kwargs):
        if x < 0:
            raise ValueError('negative')
        return fn(x, *args, **kwargs)
    return wrapper

@ensure_non_negative
def double(x):
    return x * 2
